Console.WriteLine("|---:|---:|---:|---:|");
foreach (int size in new[] { 1000, 10000, 50000 })
{
    string sample = prose[..size];
    CheckTop(MostFrequentSlow(sample, limit), MostFrequentFast(sample, limit));
